"""Build an auditable report from measured artifacts, including incomplete runs."""
import hashlib,json,pathlib,subprocess
R=pathlib.Path(__file__).resolve().parents[1]
def read(name,default=None):
 p=R/'reports'/name;return json.loads(p.read_text()) if p.exists() else default
cleanup=read('retrain-cleanup.json');audit=read('retrain-resample-audit.json');held=read('retrain-heldout.json');samples=read('retrain-asr.json',[]);checkpoints=read('retrain-checkpoints.json');health=read('retrain-health.json');hermes=read('retrain-hermes-result.json');audio=read('retrain-hermes-audio.json')
p=R/'reports/retrain-epochs.jsonl';epochs=list(map(json.loads,p.read_text().splitlines())) if p.exists() else []
# A restarted epoch supersedes an earlier record only if it completed again.
epochs=list({(e['stage'],e['epoch']):e for e in epochs}.values());epochs.sort(key=lambda e:(e['stage'],e['epoch']))
test=[x for x in samples if x['group']=='heldout-style-new-text'];vocab=[x for x in samples if x['group']=='vocabulary'];words=sum(x['reference_words'] for x in test);errors=sum(x['word_errors'] for x in test)
commit=subprocess.check_output(['git','-C','/home/voiceuser/.hermes/cache/voices/she-xtts','rev-parse','HEAD'],text=True).strip()
verification={'complete':bool(health and hermes and audio and len(samples)==40),'cleanup':cleanup,'dataset_commit':commit,'resampling':audit,'heldout':held,'epochs':epochs,'convergence':{s:read(f'retrain-{s}-convergence.json') for s in ['s1','s2']},'checkpoints':checkpoints,'heldout_style_new_text_wer':errors/words if words else None,'heldout_word_errors':errors,'heldout_reference_words':words,'sample_results':samples,'health':health,'hermes':hermes,'hermes_audio':audio}
(R/'reports/retrain-verification.json').write_text(json.dumps(verification,indent=2)+'\n')
text=['# She V2ProPlus retraining', '', 'Status: '+('complete' if verification['complete'] else 'IN PROGRESS; verification and deployment are not yet complete.'),'',f"Dataset cleanup commit: `{commit}`. Dropped 39 clips by exact filename, from {cleanup['before_clips']} ({cleanup['before_hours']:.6f} h) to {cleanup['after_clips']} ({cleanup['after_hours']:.6f} h). Every surviving manifest row resolves to a WAV, and every WAV has a manifest row: 1178 in each direction. Original manifest backup: `manifest.csv.bak-pre-drop-39`. Removed audio is retained in `.drop-39-backup/`; original `data/` parquet shards also retain every clip. Surviving source WAVs and transcript strings were not edited.", '', 'Dropped filenames: '+', '.join('`'+n+'`' for n in cleanup['dropped']), '', 'Rebuilt `data/she.list`: 1178 lines, absolute paths, single speaker she, language en, verbatim manifest texts. FFmpeg libsoxr precision 28 resampling to 32000 Hz mono PCM s16le. All 1178 output headers independently checked with ffprobe. No dropped filenames in the rebuilt list or resampled WAVs. Baseline resampled files moved to ignored `experiments/baseline-source/`; the old experiment and checkpoints remain intact.', '', '## Decisions and budget', '', '- Use an isolated `experiments/she-retrain-v2proplus` experiment and `checkpoints/retrain/` exports, retaining the 20-clip exclusion in the final model (no second all-data run).', '- Hold out 20 filenames sampled from sorted surviving filenames with Python Random seed 20261112; train on 1158. Filenames are recorded in `retrain-heldout.json`. Held-out audio and tokens are absent from both training loaders; inference uses a training-only reference.', '- Start with GPT 20 and SoVITS 25 epochs, then extend by 5 epochs until each monitored metric plateaus. Compare the previous five-epoch mean with the last five: meaningful loss improvement is >0.5%; meaningful top-3 accuracy improvement is >0.002 absolute. S1 monitors loss and top-3 accuracy; s2 monitors generator total, mel and KL losses. Upstream s2 has no accuracy metric; none is invented. Final individual epoch deltas and both window means are recorded in convergence JSON.', '- Retain PyTorch 2.5.1+cu124, Python 3.11, batch 2, fp16, gradient checkpointing and all upstream model/loss/rate settings. GPT upstream manual accumulation steps every four batches, with its existing boundary behavior; report measured optimizer steps rather than infer them from clips. SoVITS global_step counts paired generator/discriminator updates; each optimizer makes that many updates.', '- Use the dedicated ProPlus architecture for semantic extraction, removing the duplicate model.version key only in a generated local config. No upstream code changes.', '- Twenty predeclared novel narrative prompts are paired with held-out clip identities for a style-conditioned generalization evaluation. They are new text, not the held-out original transcripts. This measures novel-text intelligibility on an excluded-corpus model; it is not a teacher-forced held-out likelihood or original-audio reconstruction score.', '- Evaluate 20 fixed ordinary words including server; report corpus frequency and float32 ASR rendering without adding corpus or changing prompts/seeds after seeing results.', '- Use systemd background execution with per-epoch full optimizer checkpoints and inference exports. Stop only the TTS service during GPU work; never stop, restart, reload or edit hermes-gateway.service. No live Telegram messages.', '', '## Per-epoch curves', '', '| Stage | Epoch | Seconds | Optimizer steps this epoch | Cumulative optimizer steps | Mean logged metrics |','|---|---:|---:|---:|---:|---|']
for stage in ['s1','s2']:
 prior=0
 for e in [x for x in epochs if x['stage']==stage]:
  steps=e.get('optimizer_steps',e['global_step']-prior);prior=e['global_step'];m=e['metrics'];keys=['total_loss_epoch','top_3_acc_epoch'] if stage=='s1' else sorted(k for k in m if k.startswith('loss/'))
  text.append(f"| {stage} | {e['epoch']} | {e['seconds']:.2f} | {steps} | {e['global_step']} | "+'; '.join(f'{k}={m[k]:.6f}' for k in keys if k in m)+' |')
for stage in ['s1','s2']:
 c=verification['convergence'][stage]
 text+=['',f'### {stage} convergence', '',json.dumps(c,indent=2) if c else 'Pending. Do not infer convergence from the epoch floor.']
text+=['','## Verification','',f'Held-out-style novel-text micro WER: {errors/words:.6%} ({errors}/{words} words).' if words else 'Held-out WER: pending.', '', 'Checkpoint provenance: `'+json.dumps(checkpoints)+'`', '', 'All evaluation audio headers, volumedetect levels, exact ASR transcripts and word edit distances are recorded in `retrain-verification.json`. ASR uses faster-whisper large-v3 float32 with PYTHONPATH cleared and TTS stopped. Each prompt gets one fixed-seed synthesis attempt; failed words are retained and reported.']
if vocab:
 text+=['','| Word | Corpus count | Rendered target | WER |','|---|---:|---|---:|']
 text += [f"| {x['word']} | {x['corpus_occurrences']} | {x['target_word_rendered']} | {x['wer']:.4f} |" for x in vocab]
 text+=['',f"Coverage: {sum(x['corpus_occurrences']>0 for x in vocab)}/{len(vocab)} ordinary words present in corpus; {sum(x['target_word_rendered'] for x in vocab)}/{len(vocab)} targets rendered according to float32 ASR. This observation does not trigger corpus changes."]
text+=['','Provider health: `'+json.dumps(health)+'`','','Real Hermes Python 3.14 result: `'+json.dumps(hermes)+'`','','OGG/Opus evidence: `'+json.dumps(audio)+'`','','## Resume','','Run `systemctl --user start she-retraining.service` after a failure (or `restart` to resume an interrupted process). For a fresh host session: `systemctl --user daemon-reload` after installing `configs/she-retraining.service` in `~/.config/systemd/user/`. The enabled unit starts on user-manager startup. GPT reloads the latest full Lightning checkpoint; SoVITS reloads the latest generator/discriminator checkpoints with optimizer state. Check both G/D files share the same step before resuming an interrupted checkpoint write. Resume repeats incomplete epochs. Inspect `reports/retrain-status.json`, `reports/retrain-epochs.jsonl` and `logs/retrain-*.log`. Direct alternative: `bash scripts/run_retraining.sh`. Do not run two copies. No gateway restart is needed.','','## Failures','','Exact observed failures and remedies are in `retrain-failures.md`; full tracebacks remain in logs.']
(R/'reports/retrain-report.md').write_text('\n'.join(text)+'\n')
